    public void testCreateNumber_DoubleDash() {
        assertNull(NumberUtils.createNumber("--123"));
    }

    @Test
    public void testCreateNumber_Hex() {
        // Assuming createInteger handles hex
        assertTrue(NumberUtils.createNumber("0x10") instanceof Integer);
        assertTrue(NumberUtils.createNumber("-0x10") instanceof Integer);
    }

    @Test
    public void testCreateNumber_IntegerTypes() {
        assertTrue(NumberUtils.createNumber("123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("1234567890123456789") instanceof BigInteger);
        assertTrue(NumberUtils.createNumber("-123") instanceof Integer);
    }

    @Test
    public void testCreateNumber_LongSuffix() {
        // Test 'l' and 'L' suffixes
        assertTrue(NumberUtils.createNumber("123l") instanceof Long);
        assertTrue(NumberUtils.createNumber("123L") instanceof Long);

        // Test too big for long -> BigInteger
        // Using a very large number string
        String hugeLong = "9223372036854775808L"; 
        assertTrue(NumberUtils.createNumber(hugeLong) instanceof BigInteger);

        // Test invalid suffix case for L
        try {
            NumberUtils.createNumber("12.3L");
            fail("Should throw NumberFormatException for decimal with L suffix");
        } catch (NumberFormatException e) {}
    }

    @Test
    public void testCreateNumber_FloatSuffix() {
        // Test 'f' and 'F'
        assertTrue(NumberUtils.createNumber("123.45f") instanceof Float);
        assertTrue(NumberUtils.createNumber("123.45F") instanceof Float);

        // Test fallback to Double/BigDecimal if float is inappropriate
        // (Though usually 'f' forces float unless it's infinite/zero-precision issue)
        assertTrue(NumberUtils.createNumber("1.23e100f") instanceof Double || 
                   NumberUtils.createNumber("1.23e100f") instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_DoubleSuffix() {
        // Test 'd' and 'D'
        assertTrue(NumberUtils.createNumber("123.45d") instanceof Double);
        assertTrue(NumberUtils.createNumber("123.45D") instanceof Double);

        // Test fallback to BigDecimal
        // A number too large for Double
        String hugeDouble = "1e1000d";
        assertTrue(NumberUtils.createNumber(hugeDouble) instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_DecimalAndExp() {
        // Decimal only
        assertTrue(NumberUtils.createNumber("123.456") instanceof Float || 
                   NumberUtils.createNumber("123.456") instanceof Double || 
                   NumberUtils.createNumber("123.456") instanceof BigDecimal);

        // Exponent only
        assertTrue(NumberUtils.createNumber("1e10") instanceof Float || 
                   NumberUtils.createNumber("1e10") instanceof Double || 
                   NumberUtils.createNumber("1e10") instanceof BigDecimal);

        // Both
        assertTrue(NumberUtils.createNumber("1.23e10") instanceof Float || 
                   NumberUtils.createNumber("1.23e10") instanceof Double || 
                   NumberUtils.createNumber("1.23e10") instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_InvalidFormats() {
        // Invalid exponent position
        try {
            NumberUtils.createNumber("1.2e"); // expPos check
            fail();
