        SubLine line2 = new SubLine(new Vector2D(0, 10), new Vector2D(10, 0));

        Vector2D result = line1.intersection(line2, false);

        assertNotNull(result);
        assertEquals(5.0, result.getX(), EPSILON);
        assertEquals(5.0, result.getY(), EPSILON);
    }

    @Test
    public void testIntersection_AtEndPoint_IncludeEndPointsTrue() {
        // Line 1: (0,0) to (10,10)
        // Line 2: (10,10) to (20,10)
        // Intersection at (10,10) which is an endpoint
        SubLine line1 = new SubLine(new Vector2D(0, 0), new Vector2D(10, 10));
        SubLine line2 = new SubLine(new Vector2D(10, 10), new Vector2D(20, 10));

        Vector2D result = line1.intersection(line2, true);

        assertNotNull(result);
        assertEquals(10.0, result.getX(), EPSILON);
        assertEquals(10.0, result.getY(), EPSILON);
    }

    @Test
    public void testIntersection_AtEndPoint_IncludeEndPointsFalse() {
